class Solution
{
public:
    ListNode* plusOne(ListNode* head)
    {
        ListNode dummy(0);
        dummy.next = head;
        ListNode* lastNonNine = &dummy;
        for (ListNode* p = head; p; p = p->next)
        {
            if (p->val != 9) lastNonNine = p;
        }
        ++lastNonNine->val;
        for (ListNode* p = lastNonNine->next; p; p = p->next)
        {
            p->val = 0;
        }
        return dummy.val ? new ListNode(dummy.val, head) : head;
    }
};
